mapper.select:
SELECT 
FROM production_task pt
JOIN material_template mt ON mt.id = pt.template_id
WHERE pt.user_id = #{userId}
AND pt.status = #{status}
ORDER BY pt.created_at DESC, pt.id DESC

mapper.update:
UPDATE production_task
SET stage = #{nextStage}, updated_at = #{now}, version = version + 1
WHERE id = #{id} AND status = 'PROCESSING' AND stage = #{expectedStage}
